{"command":"cd /work/workspace/documents && (command -v pdftotext && pdftotext cda_certidao_divida_ativa.pdf - ) 2>/dev/null | head -80 || python3 - <<'EOF'
import re, zlib
raw = open('cda_certidao_divida_ativa.pdf','rb').read()
# extract text from flate streams and literal text-show operators
texts = []
for m in re.finditer(rb'stream\r?\n(.*?)endstream', raw, re.S):
    data = m.group(1)
    try: data = zlib.decompress(data)
    except Exception: pass
    for t in re.findall(rb'\((.*?)\)\s*Tj', data):
        texts.append(t.decode('latin-1'))
    for arr in re.findall(rb'\[(.*?)\]\s*TJ', data, re.S):
        parts = re.findall(rb'\((.*?)\)', arr)
        texts.append(''.join(p.decode('latin-1') for p in parts))
print('\n'.join(texts) if texts else 'NO TEXT EXTRACTED')
EOF"}

